// src/cache.ts
import crypto from 'crypto';
import fs from 'fs';
import path from 'path';
import { Page } from './plugin';

export interface ManifestEntry {
  hash: string;
  slug: string;
  lastBuilt: number;
}

export interface CacheManifest {
  templates?: string;
  pages: Record<string, ManifestEntry>;
}

export interface BuildStats {
  totalPages: number;
  pagesBuilt: number;
  pagesSkipped: number;
  timeSaved: string;
}

export function hashContent(content: string): string {
  return crypto.createHash('md5').update(content).digest('hex');
}

export function hashFile(filePath: string): string {
  try {
    const content = fs.readFileSync(filePath, 'utf-8');
    return hashContent(content);
  } catch {
    return '';
  }
}

function hashDirectoryTemplates(dir: string): string {
  if (!fs.existsSync(dir)) return '';
  const hashes: string[] = [];
  function collectHashes(d: string): void {
    const entries = fs.readdirSync(d);
    for (const entry of entries.sort()) {
      const fullPath = path.join(d, entry);
      if (fs.statSync(fullPath).isDirectory()) {
        collectHashes(fullPath);
      } else if (entry.endsWith('.hbs')) {
        hashes.push(hashFile(fullPath));
      }
    }
  }
  collectHashes(dir);
  return hashContent(hashes.join(''));
}

function loadManifest(manifestPath: string): CacheManifest | null {
  try {
    if (fs.existsSync(manifestPath)) {
      const raw = fs.readFileSync(manifestPath, 'utf-8');
      return JSON.parse(raw);
    }
  } catch {}
  return null;
}

function saveManifest(manifestPath: string, manifest: CacheManifest): void {
  const dir = path.dirname(manifestPath);
  fs.mkdirSync(dir, { recursive: true });
  fs.writeFileSync(manifestPath, JSON.stringify(manifest, null, 2));
}

export class BuildCache {
  private contentDir: string;
  private outputDir: string;
  private templatesDir?: string;
  private manifestPath: string;
  private manifest: CacheManifest | null;
  private currentTemplateHash: string = '';
  private inMemoryHtmlCache: Map<string, string>;
  private inMemoryFmCache: Map<string, Page>;
  public stats: BuildStats;

  constructor(contentDir: string, outputDir: string, templatesDir?: string) {
    this.contentDir = contentDir;
    this.outputDir = outputDir;
    this.templatesDir = templatesDir;
    this.manifestPath = path.join(contentDir, '.ssg-cache.json');
    this.manifest = loadManifest(this.manifestPath);
    this.inMemoryHtmlCache = new Map();
    this.inMemoryFmCache = new Map();
    this.stats = { totalPages: 0, pagesBuilt: 0, pagesSkipped: 0, timeSaved: '0ms' };
  }

  hasValidManifest(): boolean {
    return this.manifest !== null;
  }

  clear(): void {
    try {
      if (fs.existsSync(this.manifestPath)) {
        fs.unlinkSync(this.manifestPath);
      }
    } catch {}
    this.manifest = null;
    this.inMemoryHtmlCache.clear();
    this.inMemoryFmCache.clear();
  }

  shouldSkipPage(filePath: string): boolean {
    if (!this.manifest) return false;
    const currentHash = hashFile(filePath);
    const entry = this.manifest.pages[filePath];
    if (!entry) return false;
    if (entry.hash !== currentHash) return false;

    // Also check that template hash hasn't changed
    if (this.templatesDir) {
      const tplHash = this.getCurrentTemplateHash();
      if (this.manifest.templates !== tplHash) return false;
    }

    // Check that the output file exists
    if (entry.slug) {
      const outputPath = path.join(this.outputDir, `${entry.slug}.html`);
      if (!fs.existsSync(outputPath)) return false;
    }

    return true;
  }

  getCurrentTemplateHash(): string {
    if (!this.currentTemplateHash && this.templatesDir) {
      this.currentTemplateHash = hashDirectoryTemplates(this.templatesDir!);
    }
    return this.currentTemplateHash;
  }

  updateManifest(filePath: string, slug: string): void {
    if (!this.manifest) {
      this.manifest = { pages: {} };
    }

    const currentHash = hashFile(filePath);
    this.manifest.pages[filePath] = { hash: currentHash, slug, lastBuilt: Date.now() };

    if (this.templatesDir) {
      this.manifest.templates = this.getCurrentTemplateHash();
    }
  }

  removeStaleEntries(currentFiles: Set<string>): void {
    if (!this.manifest) return;
    for (const key of Object.keys(this.manifest.pages)) {
      if (!currentFiles.has(key)) {
        delete this.manifest.pages[key];
      }
    }
  }

  save(): void {
    if (this.manifest) {
      saveManifest(this.manifestPath, this.manifest);
    }
  }

  cacheHtml(key: string, html: string): void {
    this.inMemoryHtmlCache.set(key, html);
  }

  getCachedHtml(key: string): string | undefined {
    return this.inMemoryHtmlCache.get(key);
  }

  cacheFrontmatter(key: string, page: Page): void {
    this.inMemoryFmCache.set(key, page);
  }

  getCachedFrontmatter(key: string): Page | undefined {
    return this.inMemoryFmCache.get(key);
  }

  computeFileHash(filePath: string): string {
    return hashFile(filePath);
  }

  reportStats(): void {
    const { totalPages, pagesBuilt, pagesSkipped } = this.stats;
    const total = pagesBuilt + pagesSkipped;
    const skippedPercent = total > 0 ? Math.round((pagesSkipped / total) * 100) : 0;
    const avgTimePerPage = 50; // ms, rough estimate
    const savedMs = pagesSkipped * avgTimePerPage;
    this.stats.timeSaved = `${savedMs}ms`;

    console.log(`Build stats: ${pagesBuilt} built, ${pagesSkipped} skipped (${savedMs}ms saved, ~${skippedPercent}% cached)`);
  }
}

