```typescript
export function generateSite(
  contentDir: string, 
  outputDir: string, 
  templatesDir?: string,
  buildOptions?: { incremental?: boolean; clean?: boolean }
): number {
  const incremental = buildOptions?.incremental ?? false;
  const clean = buildOptions?.clean ?? false;

  const plugins: Plugin[] = [
    new MarkdownPlugin(),
    new TemplatePlugin(),
    ...loadPluginsFromConfig(),
  ];

  const options: BuildOptions = { contentDir, outputDir, templatesDir, incremental, clean };

  for (const p of plugins) if (p.onStart) p.onStart();
  for (const p of plugins) if (p.beforeBuild) p.beforeBuild(options);

  const allFiles = readContentDirEntries(contentDir); // just gets file names + paths
  if (allFiles.length === 0) {
    console.log(`No markdown files found in ${contentDir}`);
    for (const p of plugins) if (p.onEnd) p.onEnd();
    return 0;
  }

  fs.mkdirSync(outputDir, { recursive: true });

  const engine = templatesDir ? new TemplateEngine(templatesDir) : null;
  const useTemplates = engine && engine.initialized;

  // Set up cache
  const cache = new BuildCache(contentDir, outputDir, templatesDir);
  if (clean) {
    cache.clear();
  }

  let builtCount = 0;
  let skippedCount = 0;
  const allPages: Page[] = [];

  for (const fileEntry of allFiles) {
    if (incremental && cache.shouldSkipPage(fileEntry.fullPath)) {
      skippedCount++;
      // We still need the page object for index generation
      // Re-parse it (fast) or get from cache
      let page = cache.getCachedFrontmatter(fileEntry.fullPath);
      if (!page) {
        page = parseMarkdownFile(fileEntry.fullPath)!;
        cache.cacheFrontmatter(fileEntry.fullPath, page);
      }
      allPages.push(page);
      continue;
    }

    builtCount++;
    let page = parseMarkdownFile(fileEntry.fullPath)!;
    cache.cacheFrontmatter(fileEntry.fullPath, page);

    for (const p of plugins) {
      if (p.onFile) page = p.onFile(page);
    }

    const html = useTemplates
      ? (engine!.render(page) || renderPage(page))
      : renderPage(page);

    cache.cacheHtml(fileEntry.fullPath, html);
    fs.writeFileSync(path.join(outputDir, `${page.slug}.html`), html);

    allPages.push(page);
    cache.updateManifest(fileEntry.fullPath, page.slug);
  }

  // Remove stale entries for deleted files
  const currentFiles = new Set(allFiles.map(f => f.fullPath));
  cache.removeStaleEntries(currentFiles);

  // Always rebuild index
  const indexHtml = useTemplates
    ? (engine!.renderIndex(allPages) || renderIndex(allPages))
    : renderIndex(allPages);
  fs.writeFileSync(path.join(outputDir, 'index.html'), indexHtml);
  builtCount++; // index counts as 1 built

  cache.stats = {
    totalPages: allFiles.length + 1,
    pagesBuilt: builtCount,
    pagesSkipped: skippedCount,
    timeSaved: '0ms',
  };

  cache.save();

  if (incremental) {
    cache.reportStats();
  }

  for (const p of plugins) if (p.afterBuild) p.afterBuild(options);
  for (const p of plugins) if (p.onEnd) p.onEnd();

  const total = builtCount + skippedCount;
  console.log(`Generated ${total} files in ${outputDir}`);
  return total;
}
