    writeFile(contentDir, 'a.md', '---\ntitle: A\n---\nContent A');

    generateSite(contentDir, outputDir, undefined, { incremental: true });

    const idx1 = fs.readFileSync(path.join(outputDir, 'index.html'), 'utf-8');
